import{_ as s,o as a,c as t,a2 as e}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"ADR-0005: memorize — 注入式 LLM，两种宿主驱动写入（后台抽取 / Agent 工具）","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0005-memorize-injected-llm.md","filePath":"adr/0005-memorize-injected-llm.md","lastUpdated":1785239344000}'),n={name:"adr/0005-memorize-injected-llm.md"};function l(o,i,r,h,d,p){return a(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="adr-0005-memorize-—-注入式-llm-两种宿主驱动写入-后台抽取-agent-工具" tabindex="-1">ADR-0005: memorize — 注入式 LLM，两种宿主驱动写入（后台抽取 / Agent 工具） <a class="header-anchor" href="#adr-0005-memorize-—-注入式-llm-两种宿主驱动写入-后台抽取-agent-工具" aria-label="Permalink to &quot;ADR-0005: memorize — 注入式 LLM，两种宿主驱动写入（后台抽取 / Agent 工具）&quot;">​</a></h1><ul><li><strong>状态</strong>：Proposed（2026-07-24，随 PR 评审定稿）</li><li><strong>日期</strong>：2026-07-24</li><li><strong>关联</strong>：<a href="./0001-diary-store.html">ADR-0001</a>（日记原语，写入对象）、<a href="./0004-api-contract-thin-shells.html">ADR-0004</a>（契约 = Python API，壳内无业务逻辑）、<a href="https://github.com/XnneHangLab/XnneHangLab/blob/dev/docs/adr/0001-llm-mode-memory.md" target="_blank" rel="noreferrer">XnneHangLab ADR-0001</a>（硬约束：框架零 LLM、memorize ≤1 次由宿主发起）、<a href="https://github.com/XnneHangLab/XnneHangLab/blob/dev/docs/adr/0002-memu-design-not-dependency.md" target="_blank" rel="noreferrer">XnneHangLab ADR-0002</a>（借鉴 memU 设计而非引入依赖）、<code>docs/guide/writing-diary.md</code>（参考提示词）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>硬约束 2：<strong>框架本体零 LLM</strong>；memorize 至多 1 次 LLM 调用、由宿主发起。参考提示词（<code>writing-diary</code>）已经给出&quot;日记怎么写&quot;，但没规定宿主&quot;怎么调 LLM&quot; —— 而宿主接入时冒出<strong>两种自然形态</strong>，二者都该支持，且都走<strong>注入</strong>（框架不捆绑 provider/keys）：</p><ol><li><strong>不想等</strong>：对话不该为写日记阻塞。希望抽取在后台异步跑完，用户无感。</li><li><strong>Agent 自己写</strong>：角色在对话里主动说&quot;哇，这个我帮你记下来&quot;，把写日记当成一个 <strong>skill / tool</strong> 来调用，愿意为此花点时间。</li></ol><p>mem0 / memU 把 memorize LLM 连同 provider 一起塞进库里。我们不这么做（XnneHangLab ADR-0002 的教训 + 硬约束 1 零基础设施）：宿主本来就有 LLM，框架只提供&quot;配方&quot;（提示词 + schema + 校验 + append），<strong>LLM 实例由宿主注入</strong>。问题是：把这份&quot;配方&quot;以什么形状交给这两种宿主。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><h3 id="_1-定义一个极小的-llm-端口-protocol" tabindex="-1">1. 定义一个极小的 LLM 端口（Protocol） <a class="header-anchor" href="#_1-定义一个极小的-llm-端口-protocol" aria-label="Permalink to &quot;1. 定义一个极小的 LLM 端口（Protocol）&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> LLM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Protocol</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> complete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self, prompt: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span></code></pre></div><p>宿主用自己的客户端实现它（同步或异步各出一个 Protocol）。框架<strong>永不捆绑</strong> LLM / provider / keys —— 与 <code>Embedder</code> 端口同一套路：能力由注入而来，核心零依赖不破。</p><h3 id="_2-模式-a-—-后台抽取-别让我等" tabindex="-1">2. 模式 A — 后台抽取（&quot;别让我等&quot;） <a class="header-anchor" href="#_2-模式-a-—-后台抽取-别让我等" aria-label="Permalink to &quot;2. 模式 A — 后台抽取（&quot;别让我等&quot;）&quot;">​</a></h3><p>宿主在一轮结束后，把 <code>memorize(...)</code> 当<strong>后台异步任务</strong>跑；框架负责编排，一次 LLM 调用、脱离对话关键路径：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> memorize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(diary, turn, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, llm: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LLM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ...) -&gt; list[DiaryEntry]:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    raw </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> llm.complete(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DIARY_PROMPT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.format(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">turn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">turn))  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 参考提示词</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [diary.append(e[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">meta) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> e </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> _parse(raw)]  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 解析 + 落盘</span></span></code></pre></div><p>这就是 mem0/memU 的便利（&quot;调一个函数，得到记忆&quot;），只是那次 LLM 调用用的是<strong>注入的</strong> <code>llm</code>。异步与后台调度归宿主（框架也可另出一个 <code>amemorize</code> 便利）。</p><h3 id="_3-模式-b-—-agent-工具-skill-我帮你写日记" tabindex="-1">3. 模式 B — Agent 工具 / skill（&quot;我帮你写日记&quot;） <a class="header-anchor" href="#_3-模式-b-—-agent-工具-skill-我帮你写日记" aria-label="Permalink to &quot;3. 模式 B — Agent 工具 / skill（&quot;我帮你写日记&quot;）&quot;">​</a></h3><p>框架提供一个 <strong>tool 定义（function-call schema）+ handler</strong>：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">diary_tool()  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -&gt; 一个 function-call schema：append_diary(content: str, ...)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">handle_diary_tool(diary, args) </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DiaryEntry   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 把工具调用参数落盘</span></span></code></pre></div><p>宿主把该 tool 注册进自己的 Agent；当角色在对话中决定记一笔，Agent 调用它，handler 落盘 <code>diary.append()</code>。<strong>内容由 Agent 当场自己写</strong>（它就是回路里的 LLM），<strong>没有额外的抽取调用</strong>；同步发生在这一轮内 —— 会花点时间，但那是角色的主动动作，用户看得见。</p><h3 id="_4-两者都注入、都可选、核心仍零-llm" tabindex="-1">4. 两者都注入、都可选、核心仍零 LLM <a class="header-anchor" href="#_4-两者都注入、都可选、核心仍零-llm" aria-label="Permalink to &quot;4. 两者都注入、都可选、核心仍零 LLM&quot;">​</a></h3><ul><li>模式 A / B 都用宿主的 LLM / Agent，<strong>opt-in</strong>；<strong>框架直接发起的 LLM 调用数为零</strong>（注入的 callable 不算，与 embedder 同理），仍满足&quot;≤1 次、由宿主发起&quot;。</li><li><strong>同一份参考提示词服务两者</strong>：模式 A 把它喂给抽取调用；模式 B 把它的文风规则写进 tool description。</li><li>&quot;写得不如我们想要&quot;的风险由框架侧兜住：<strong>提示词 + JSON schema + 写入校验 + append 都在框架</strong>，宿主只管 LLM 接线。</li></ul><h3 id="_5-边界-壳内无业务逻辑-adr-0004" tabindex="-1">5. 边界（壳内无业务逻辑，ADR-0004） <a class="header-anchor" href="#_5-边界-壳内无业务逻辑-adr-0004" aria-label="Permalink to &quot;5. 边界（壳内无业务逻辑，ADR-0004）&quot;">​</a></h3><p><code>memorize()</code> 与 tool handler 是<strong>编排</strong>（提示词 → 调用 → 解析 → append），不是检索/融合规则。它们不改变 diary/wiki 的语义，只把&quot;注入的 LLM 产出&quot;变成&quot;合规的条目&quot;。写什么、何时写、什么文风仍是宿主策略（ADR-0001）；框架给的是可复现的默认配方。</p><h2 id="理由" tabindex="-1">理由 <a class="header-anchor" href="#理由" aria-label="Permalink to &quot;理由&quot;">​</a></h2><ul><li>两种真实形态：<strong>自动后台记日记</strong>（无感、不打断）vs <strong>角色主动记一笔</strong>（有感、&quot;角色选择了记住这件事&quot;）。陪伴场景两者都要。</li><li>都走注入 → 零耦合、provider 无关，守住硬约束 2（框架不直接调 LLM）。</li><li>便利性（mem0/memU 的卖点）拿到了，耦合（provider / keys / 通用文风）没背上。</li></ul><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><p><strong>正面</strong></p><ul><li>宿主拿到 mem0/memU 式便利，但无耦合；后台与主动两种记法都支持。</li><li>核心仍零 LLM / 零依赖（LLM 经端口注入）。</li><li>一致性（&quot;写得如我们想要&quot;）有了框架侧抓手：提示词 + schema + 校验。</li></ul><p><strong>负面 / 代价</strong></p><ul><li>新增可选面：<code>LLM</code> 端口、<code>memorize()</code> helper、tool 定义 / handler，需维护。</li><li>tool schema 与抽取 JSON schema 成为兼容面，随语义化版本管理。</li><li>同步与异步端口二选一还是都给，实现期定。</li></ul><p><strong>实施</strong></p><ul><li>参考提示词已落地（PR #22）。<strong>Phase 2</strong>：<code>LLM</code> 端口 + <code>memorize()</code>（模式 A）+ <code>diary_tool()</code> / handler（模式 B）+ 测试；<code>writing-diary</code> 指南扩写两种模式的接法。全部可选、零依赖核心不破。</li></ul>`,31)])])}const c=s(n,[["render",l]]);export{g as __pageData,c as default};
